1	import { access, cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
2	import { spawn } from 'node:child_process';
3	import { basename, dirname, join, relative, resolve } from 'pathe';
4	import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
5	import {
6		ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS,
7		ANGULAR_TINY_TRANSLATOR_FIXTURE,
8		ANGULAR_TINY_TRANSLATOR_SOURCE,
9		parseWitnessAngularTinyTranslatorReceipt,
10		renderWitnessAngularTinyTranslatorReceipt,
11		WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS,
12		WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE,
13		WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE,
14		WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES,
15		WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE,
16		WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE,
17		WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA,
18		WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES,
19		WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES,
20		witnessAngularTinyTranslatorBehaviorDigest,
21		witnessAngularTinyTranslatorDigest,
22		witnessAngularTinyTranslatorRawDigest,
23		type WitnessAngularTinyTranslatorMutation,
24		type WitnessAngularTinyTranslatorReceipt,
25		type WitnessAngularTinyTranslatorRun,
26	} from '../../../core/src/receipts/witness-angular-tiny-translator.ts';
27	import {
28		WITNESS_DOWNLOAD_CAPTURE_RULE,
29		WITNESS_FILE_INPUT_LOAD_RULE,
30	} from '../../../core/src/receipts/witness-real-app.ts';
31	import {
32		executeAngularTinyTranslatorWitnessRun,
33		TINY_TRANSLATOR_MUTATION_SEAM,
34		WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS,
35		WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS,
36	} from './real-app-run.ts';
37	import { verifyLinkedWitnessProvenance } from './provenance.ts';
38	
39	const root = resolve(import.meta.dirname, '../../../..');
40	const fixtureEvidence = join(root, 'evidence/runs/angular-tiny-translator-v0-12-0');
41	const witnessEvidence = join(root, 'evidence/runs/witness-angular-tiny-translator');
42	const stageRoot = join(root, '.versionless/stage/witness-angular-tiny-translator');
43	/**
44	 * The migrated lane's build tree, and the output root the u17d record pins as
45	 * canonical. The tree is a working directory rather than committed bytes, so
46	 * this proof cannot assume it survived: {@link migratedLaneRoot} regenerates it
47	 * from the committed flow when it is absent and, either way, refuses to serve
48	 * it until it matches the inventory the record published.
49	 */
50	const migratedStage = join(root, '.versionless/stage/angular-tiny-translator-v0-12-0-u17b');
51	const sourceOutputs = {
52		baseline: join(
53			root,
54			'.versionless/cache/angular-tiny-translator-v0-12-0-baseline/app/dist/rebuild-1',
55		),
56		migrated: join(migratedStage, 'dist-7'),
57	} as const;
58	/** The build the u17d record pins for the canonical output root. */
59	const MIGRATED_BUILD_COMMAND = 'npx ng build --configuration production' as const;
60	const laneFileCounts = { baseline: 524, migrated: 524 } as const;
61	
62	type InventoryEntry = { path: string; sha256: string; bytes: number };
63	
64	async function exists(path: string): Promise<boolean> {
65		return access(path).then(
66			() => true,
67			() => false,
68		);
69	}
70	
71	async function files(directory: string): Promise<string[]> {
72		const output: string[] = [];
73		for (const entry of await readdir(directory, { withFileTypes: true })) {
74			const path = join(directory, entry.name);
75			if (entry.isDirectory()) output.push(...(await files(path)));
76			else if (entry.isFile()) output.push(path);
77		}
78		return output.sort();
79	}
80	
81	/** Every file of an emitted artifact, addressed exactly as the u17d record does. */
82	async function inventoryOf(rootDirectory: string): Promise<InventoryEntry[]> {
83		const entries: InventoryEntry[] = [];
84		for (const file of await files(rootDirectory)) {
85			const bytes = await readFile(file);
86			entries.push({
87				path: relative(rootDirectory, file),
88				sha256: sha256(bytes),
89				bytes: bytes.length,
90			});
91		}
92		return entries;
93	}
94	
95	/** The pinned migrated build record, re-read rather than restated. */
96	async function migratedLaneRecord(): Promise<{
97		inventory: InventoryEntry[];
98		inventorySha256: string;
99	}> {
100		const pinned = ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.find(
101			(receipt) => receipt.lane === 'migrated',
102		);
103		if (pinned === undefined) throw new Error('TinyTranslator migrated lane binding is absent');
104		const bytes = await readFile(join(root, pinned.path));
105		if (sha256(bytes) !== pinned.sha256)
106			throw new Error(`TinyTranslator bound build receipt bytes drifted: ${pinned.path}`);
107		const record = JSON.parse(bytes.toString('utf8')) as {
108			inventory?: InventoryEntry[];
109			determinism?: { inventorySha256?: string };
110		};
111		const inventory = record.inventory;
112		const inventorySha256 = record.determinism?.inventorySha256;
113		if (!Array.isArray(inventory) || typeof inventorySha256 !== 'string')
114			throw new Error('TinyTranslator migrated lane record publishes no inventory to verify');
115		return { inventory, inventorySha256 };
116	}
117	
118	/**
119	 * The digest the u17d record computed over its own inventory: the pretty-printed
120	 * JSON array with a trailing newline, exactly as the recording flow wrote it.
121	 * Recomputing it here rather than accepting the record's own number is what
122	 * makes the comparison a check instead of a restatement.
123	 */
124	function inventoryDigest(inventory: readonly InventoryEntry[]): string {
125		return sha256(`${JSON.stringify(inventory, null, 2)}\n`);
126	}
127	
128	async function run(command: string, args: readonly string[], cwd: string): Promise<void> {
129		await new Promise<void>((settle, fail) => {
130			const child = spawn(command, [...args], {
131				cwd,
132				stdio: 'ignore',
133				env: {
134					...process.env,
135					VERSIONLESS_NETWORK_MODE: 'offline',
136					NPM_CONFIG_OFFLINE: 'true',
137				},
138			});
139			child.on('error', fail);
140			child.on('close', (code) =>
141				code === 0
142					? settle()
143					: fail(new Error(`TinyTranslator regeneration command failed: ${command} (${code})`)),
144			);
145		});
146	}
147	
148	/**
149	 * The migrated lane's canonical output root, regenerated when it is missing and
150	 * verified either way.
151	 *
152	 * The regeneration is the same offline production build the u17d record pins,
153	 * run over the same staged application tree that record itemises; nothing is
154	 * re-migrated here, because the migration is already applied in that tree. The
155	 * verification is what the proof actually rests on: the emitted inventory has
156	 * to reproduce the record's own 524-file inventory, file for file and digest
157	 * for digest, and its digest has to reproduce the record's `inventorySha256`.
158	 * A tree that regenerated differently is refused rather than served.
159	 */
160	async function migratedLaneRoot(): Promise<string> {
161		const record = await migratedLaneRecord();
162		if (!(await exists(sourceOutputs.migrated))) {
163			const application = join(migratedStage, 'app');
164			if (!(await exists(application)))
165				throw new Error(
166					'TinyTranslator migrated lane cannot be regenerated: the staged application tree is absent',
167				);
168			const [command, ...args] = MIGRATED_BUILD_COMMAND.split(' ');
169			await run(command!, [...args, '--output-path', sourceOutputs.migrated], application);
170		}
171		const emitted = await inventoryOf(sourceOutputs.migrated);
172		const emittedDigest = inventoryDigest(emitted);
173		if (canonicalize(emitted) !== canonicalize(record.inventory))
174			throw new Error(
175				`TinyTranslator migrated lane inventory differs from the pinned record: ${emittedDigest} against ${record.inventorySha256}`,
176			);
177		if (emittedDigest !== record.inventorySha256)
178			throw new Error(
179				`TinyTranslator migrated lane inventory digest differs: ${emittedDigest} against ${record.inventorySha256}`,
180			);
181		return sourceOutputs.migrated;
182	}
183	
184	async function stageInputs(): Promise<Record<'baseline' | 'migrated', string>> {
185		const migrated = await migratedLaneRoot();
186		const lanes = join(stageRoot, 'lanes');
187		await rm(lanes, { recursive: true, force: true });
188		const staged = { baseline: join(lanes, 'baseline'), migrated: join(lanes, 'migrated') };
189		const outputs = { baseline: sourceOutputs.baseline, migrated } as const;
190		for (const lane of ['baseline', 'migrated'] as const) {
191			if (!(await exists(outputs[lane])))
192				throw new Error(`TinyTranslator ${lane} production output is absent`);
193			await mkdir(dirname(staged[lane]), { recursive: true });
194			await cp(outputs[lane], staged[lane], { recursive: true, force: false });
195			const stagedFiles = await files(staged[lane]);
196			if (stagedFiles.length !== laneFileCounts[lane])
197				throw new Error(
198					`TinyTranslator ${lane} lane file count differs: ${stagedFiles.length} against ${laneFileCounts[lane]}`,
199				);
200		}
201		return staged;
202	}
203	
204	async function executeRuns(
205		lanes: Record<'baseline' | 'migrated', string>,
206	): Promise<WitnessAngularTinyTranslatorRun[]> {
207		const runs: WitnessAngularTinyTranslatorRun[] = [];
208		for (const lane of ['baseline', 'migrated'] as const)
209			for (const pass of [1, 2] as const) {
210				const raw = await executeAngularTinyTranslatorWitnessRun({
211					lane,
212					pass,
213					laneRoot: lanes[lane],
214					receiptRoot: join(stageRoot, 'receipts'),
215				});
216				const candidate = raw as WitnessAngularTinyTranslatorRun;
217				if (candidate.semanticDigest !== witnessAngularTinyTranslatorRawDigest(candidate))
218					throw new Error(`TinyTranslator ${lane} pass ${pass} raw digest differs`);
219				runs.push({
220					...candidate,
221					behaviorDigest: witnessAngularTinyTranslatorBehaviorDigest(candidate),
222				});
223			}
224		if (new Set(runs.map((entry) => entry.behaviorDigest)).size !== 1)
225			throw new Error('TinyTranslator baseline/migrated behavior parity differs');
226		return runs;
227	}
228	
229	/**
230	 * Byte mutation on the migrated build.
231	 *
232	 * The seam is the visible label of the control that opens the file picker: a
233	 * string a reader sees, asserted exactly by the journey on the create-project
234	 * route, and the name of the very mechanism this vertical exists to exercise.
235	 * The uniqueness demanded here is the corpus discipline — exactly one served
236	 * module may carry it, exactly once — so overwriting it in place cannot be
237	 * absorbed by a second copy elsewhere in the bundle.
238	 */
239	async function semanticMutation(
240		laneRoot: string,
241		behaviorDigest: string,
242	): Promise<WitnessAngularTinyTranslatorMutation> {
243		const expected = Buffer.from(TINY_TRANSLATOR_MUTATION_SEAM);
244		const candidates: Array<{ path: string; offset: number }> = [];
245		for (const path of await files(laneRoot)) {
246			const bytes = await readFile(path);
247			const offset = bytes.indexOf(expected);
248			if (offset < 0) continue;
249			if (bytes.lastIndexOf(expected) !== offset)
250				throw new Error('TinyTranslator semantic seam is not unique within its file');
251			candidates.push({ path, offset });
252		}
253		const target = candidates[0];
254		if (candidates.length !== 1 || target === undefined || !target.path.endsWith('.js'))
255			throw new Error('TinyTranslator semantic seam is not a single served module');
256		const before = await readFile(target.path);
257		const mutated = Buffer.from(before);
258		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
259		const beforeSha256 = sha256(before);
260		const mutatedSha256 = sha256(mutated);
261		let intendedFailure = false;
262		try {
263			await writeFile(target.path, mutated);
264			try {
265				await executeAngularTinyTranslatorWitnessRun({
266					lane: 'migrated',
267					pass: 1,
268					laneRoot,
269					receiptRoot: join(stageRoot, 'mutation-receipt'),
270				});
271			} catch (error) {
272				const message = error instanceof Error ? error.message : String(error);
273				intendedFailure = message.includes(TINY_TRANSLATOR_MUTATION_SEAM);
274			}
275		} finally {
276			await writeFile(target.path, before);
277		}
278		const afterRestoreSha256 = sha256(await readFile(target.path));
279		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
280			throw new Error('TinyTranslator semantic mutation was not exact red and byte-restored');
281		const restored = (await executeAngularTinyTranslatorWitnessRun({
282			lane: 'migrated',
283			pass: 1,
284			laneRoot,
285			receiptRoot: join(stageRoot, 'restoration-receipt'),
286		})) as WitnessAngularTinyTranslatorRun;
287		const restoredBehaviorDigest = witnessAngularTinyTranslatorBehaviorDigest(restored);
288		if (restoredBehaviorDigest !== behaviorDigest)
289			throw new Error('TinyTranslator restored browser behavior differs');
290		return {
291			failure: 'witness-semantic-assertion',
292			intendedFailure: true,
293			lane: 'migrated',
294			seam: TINY_TRANSLATOR_MUTATION_SEAM,
295			path: relative(laneRoot, target.path),
296			offset: target.offset,
297			beforeSha256,
298			mutatedSha256,
299			afterRestoreSha256,
300			restoredByteIdentically: true,
301			restoredRun: 'pass',
302			restoredBehaviorDigest,
303		};
304	}
305	
306	/**
307	 * The nonclaims this proof publishes. Each one names something a reader could
308	 * otherwise assume from the rest of the receipt and states plainly that it is
309	 * not established here.
310	 */
311	export const WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS: readonly string[] = Object.freeze([
312		'This is one Angular lineage under direct Witness and does not establish generic Angular, Angular CLI 1.5, `.angular-cli.json` workspaces, or `@angular-devkit/build-angular:browser` support.',
313		'The Angular lineage readiness score is unchanged; this vertical is not counted before Judge audit.',
314		'There is no backend and nothing was stubbed or seeded by the harness. The project the journey works on is created by the application itself, from a file this proof hands its own file input, and everything it keeps it keeps in browser local storage.',
315		'The translation file handed to the page is synthetic and authored for this proof. It carries no upstream project’s strings and no third party’s translated content, and it is bound by name, length and digest so a journey cannot quietly load a different one.',
316		'The file the page produced is read back by name, byte length and digest, and its content is asserted rather than published: a produced translation file is the application’s data, not this receipt’s.',
317		'Neither lane ends up with the Material Icons glyphs, and the two lanes fail to get them differently. Both degradations are measured and recorded rather than masked, and neither is a regression of the migration: the font seam is answered inside the browser context so that nothing leaves the machine.',
318		'Two of the four rendered-appearance probes are declared to differ across the eleven-major lift and are checked in both directions — a probe outside the declaration that differs fails the run, and a declared difference that stopped being real fails it too.',
319		'Byte parity across the lanes is not claimed and is recorded separately by the bound build receipts; eleven majors of bundler produce different file names and different byte counts by construction.',
320		'Neither build ships or registers a service worker. The browser context allowed registration and the application never attempted one, so the zero is the application’s own behavior rather than a policy imposed to produce it.',
321		'Locality is process-scoped and does not establish operating-system-wide isolation.',
322		'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
323	]);
324	
325	async function bindCanonicalReceipts(): Promise<
326		WitnessAngularTinyTranslatorReceipt['canonicalReceipts']
327	> {
328		return await Promise.all(
329			ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.map(async (pinned) => {
330				const bytes = await readFile(join(root, pinned.path));
331				const value = JSON.parse(bytes.toString('utf8')) as {
332					schemaVersion?: unknown;
333					digest?: unknown;
334				};
335				if (
336					value.schemaVersion !== pinned.schemaVersion ||
337					value.digest !== pinned.digest ||
338					sha256(bytes) !== pinned.sha256
339				)
340					throw new Error(
341						`TinyTranslator bound build receipt identity differs: ${pinned.path}`,
342					);
343				return { ...pinned };
344			}),
345		);
346	}
347	
348	export async function runWitnessAngularTinyTranslator(): Promise<WitnessAngularTinyTranslatorReceipt> {
349		if (
350			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
351			process.env.NPM_CONFIG_OFFLINE !== 'true'
352		)
353			throw new Error('TinyTranslator Witness requires dual offline controls');
354		if (await exists(witnessEvidence))
355			throw new Error('TinyTranslator Witness output collision');
356		const provenance = await verifyLinkedWitnessProvenance(root);
357		const canonicalReceipts = await bindCanonicalReceipts();
358		const lanes = await stageInputs();
359		const runs = await executeRuns(lanes);
360		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
361		const baseline = runs.find((entry) => entry.lane === 'baseline')!;
362		const migrated = runs.find((entry) => entry.lane === 'migrated')!;
363		const artifacts = join(fixtureEvidence, 'witness-artifacts');
364		await mkdir(artifacts, { recursive: true });
365		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
366			flag: 'wx',
367		});
368		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
369			flag: 'wx',
370		});
371		const receipt: WitnessAngularTinyTranslatorReceipt = {
372			schemaVersion: WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA,
373			result: 'pass',
374			fixture: ANGULAR_TINY_TRANSLATOR_FIXTURE,
375			source: ANGULAR_TINY_TRANSLATOR_SOURCE,
376			provenance,
377			canonicalReceipts,
378			runs,
379			mutation,
380			consoleErrors: {
381				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.baseline],
382				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.migrated],
383			},
384			failedRequests: {
385				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.baseline],
386				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.migrated],
387			},
388			mockedSeams: {
389				baseline: [...baseline.mockedNonLoopbackSeams.category],
390				migrated: [...migrated.mockedNonLoopbackSeams.category],
391			},
392			fontSeamDifference: WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE,
393			matIconDegradations: {
394				baseline: baseline.applicationJourney.matIcon,
395				migrated: migrated.applicationJourney.matIcon,
396			},
397			renderedStyleParity: {
398				state: 'measured-resolved-styles-with-declared-differences',
399				probes: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES.length,
400				declaredDifferences: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES,
401				otherProbesAgree: true,
402			},
403			fileInput: {
404				surfaces: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES,
405				fixture: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE,
406				rule: WITNESS_FILE_INPUT_LOAD_RULE,
407			},
408			downloads: {
409				surface: WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE,
410				rule: WITNESS_DOWNLOAD_CAPTURE_RULE,
411				captured: runs.map((entry) => ({
412					lane: entry.lane,
413					pass: entry.pass,
414					files: [...entry.downloadCaptures.captured],
415				})),
416			},
417			persistence: {
418				store: 'browser-local-storage',
419				backend: 'none',
420				stubbed: false,
421				survivesOnlineReload: true,
422			},
423			routeShape: WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE,
424			scrollAbsence: runs[0]!.scrollAbsence,
425			accommodations: WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS,
426			readiness: {
427				angularLineage: { ready: 1, total: 4, counted: false },
428				overall: { ready: 3, total: 12 },
429			},
430			locality: {
431				mode: 'offline',
432				successfulNonLoopback: 0,
433				osWideIsolation: false,
434				mockedNonLoopbackSeams: migrated.mockedNonLoopbackSeams.category.length,
435			},
436			nonclaims: [...WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS],
437			integrity: { algorithm: 'sha256', canonicalDigest: '' },
438		};
439		receipt.integrity.canonicalDigest = witnessAngularTinyTranslatorDigest(receipt);
440		parseWitnessAngularTinyTranslatorReceipt(receipt);
441		await mkdir(witnessEvidence, { recursive: true });
442		const canonical = canonicalize(receipt);
443		/**
444		 * The companion is rendered from the receipt as PUBLISHED rather than from
445		 * the object in memory: canonicalization sorts keys, so a companion rendered
446		 * from the in-memory object would disagree with the same companion rendered
447		 * from the file, and `verify` — which only ever has the file — would be
448		 * right to reject it.
449		 */
450		const published = parseWitnessAngularTinyTranslatorReceipt(JSON.parse(canonical));
451		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonical}\n`, { flag: 'wx' });
452		await writeFile(
453			join(witnessEvidence, 'receipt.md'),
454			renderWitnessAngularTinyTranslatorReceipt(published),
455			{ flag: 'wx' },
456		);
457		return published;
458	}
459	
460	export async function verifyWitnessAngularTinyTranslator(
461		output = witnessEvidence,
462	): Promise<WitnessAngularTinyTranslatorReceipt> {
463		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
464		const receipt = parseWitnessAngularTinyTranslatorReceipt(
465			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
466		);
467		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
468			throw new Error('TinyTranslator linked Witness provenance differs');
469		for (const bound of receipt.canonicalReceipts)
470			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
471				throw new Error(`TinyTranslator bound build receipt bytes drifted: ${bound.path}`);
472		if (
473			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
474			renderWitnessAngularTinyTranslatorReceipt(receipt)
475		)
476			throw new Error('TinyTranslator human Witness receipt differs');
477		const serialized = canonicalize(receipt);
478		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
479			throw new Error('TinyTranslator receipt leaks host identity');
480		return receipt;
481	}
482	
483	export async function main(args = process.argv.slice(2)): Promise<void> {
484		const publishIndex = args.indexOf('--publish');
485		const verifyIndex = args.indexOf('--verify');
486		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
487			const output = resolve(root, args[publishIndex + 1]!);
488			if (output !== witnessEvidence) throw new Error('TinyTranslator publish path differs');
489			const receipt = await runWitnessAngularTinyTranslator();
490			process.stdout.write(
491				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
492			);
493			return;
494		}
495		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
496			const receipt = await verifyWitnessAngularTinyTranslator(
497				resolve(root, args[verifyIndex + 1]!),
498			);
499			process.stdout.write(
500				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
501			);
502			return;
503		}
504		throw new Error(
505			'TinyTranslator Witness runner requires --run-twice --publish <dir> or --verify <dir>',
506		);
507	}
508	
509	if (basename(process.argv[1] ?? '') === 'angular-tiny-translator-run.ts')
510		main().catch((error: unknown) => {
511			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
512			process.exitCode = 1;
513		});
