/**
 * Calibration driver for the TinyTranslator Witness journey.
 *
 * Temporary: it runs one pass per lane against staged copies of the two pinned
 * output roots and prints whatever the journey measured or refused, so the four
 * uncalibrated journey facts can be pinned to reality rather than guessed.
 */
import { cp, mkdir, rm } from 'node:fs/promises';
import { join, resolve } from 'pathe';
import { executeAngularTinyTranslatorWitnessRun } from '../witness/real-app-run.ts';

const root = resolve(import.meta.dirname, '../../../..');
const stage = join(root, '.versionless/stage/witness-angular-tiny-translator-calibrate');
const sources = {
	baseline: join(
		root,
		'.versionless/cache/angular-tiny-translator-v0-12-0-baseline/app/dist/rebuild-1',
	),
	migrated: join(root, '.versionless/stage/angular-tiny-translator-v0-12-0-u17b/dist-7'),
} as const;

export async function main(args = process.argv.slice(2)): Promise<void> {
	const lanes = (['baseline', 'migrated'] as const).filter(
		(lane) => args.length === 0 || args.includes(lane),
	);
	for (const lane of lanes) {
		const laneRoot = join(stage, 'lanes', lane);
		await rm(laneRoot, { recursive: true, force: true });
		await mkdir(laneRoot, { recursive: true });
		await cp(sources[lane], laneRoot, { recursive: true });
		try {
			const run = await executeAngularTinyTranslatorWitnessRun({
				lane,
				pass: 1,
				laneRoot,
				receiptRoot: join(stage, 'receipts'),
			});
			process.stdout.write(
